import numpy as np
from scipy.signal import find_peaks

def zero_crossings(t, x):
    # find indices where x changes sign; linear interpolation for crossing time
    s = np.sign(x)
    # treat zeros as sign of next non-zero; but for now just attempt
    zc_idx = np.where(np.diff(np.signbit(x)))[0]
    tz = []
    for i in zc_idx:
        x1, x2 = x[i], x[i+1]
        if x2 == x1:
            continue
        # linear interpolate t where x=0
        t0 = t[i] - x1*(t[i+1]-t[i])/(x2-x1)
        tz.append(t0)
    return np.array(tz)

summaries = []
for name, arr, ts in [('A',A_arrays,A_ts),('B',B_arrays,B_ts)]:
    for i in range(arr.shape[0]):
        x = arr[i,:,0]
        tz = zero_crossings(ts, x)
        if len(tz)>3:
            periods = 2*np.diff(tz)  # zero-crossing to next zero-crossing times 2 = period approx
            summaries.append([name, i, float(np.mean(periods)), float(np.std(periods))])
        else:
            summaries.append([name, i, np.nan, np.nan])

